cards.solution:
function tambahItem(keranjang, item) {
  return [...keranjang, item];
}
function ubahQty(keranjang, nama, qty) {
  return keranjang.map((item) => (item.nama === nama ? { ...item, qty } : item));
}
const awal = [{ nama: "Kopi", qty: 1 }];
const k2 = tambahItem(awal, { nama: "Teh", qty: 2 });
const k3 = ubahQty(k2, "Kopi", 3);
console.log(awal.length, k2.length);
console.log(k2[0].qty, k3[0].qty);
console.log(k3[1] === k2[1]);
